// Web push (RFC 8030) with VAPID (RFC 8292) on the standard Web Crypto API.
// Pushes carry no content (no payload encryption needed): the phone's service worker asks the
// Hub what to show (/api/push/pending), and the Hub only ever answers with non-private text.
// The VAPID key pair is generated by the Hub itself and kept in its database (private key
// encrypted at rest), so no person ever handles it.
import { b64urlEncode, b64urlDecode } from './webauthn.js';

const subtle = () => globalThis.crypto.subtle;
const te = new TextEncoder();

// Only real browser push services: the Hub never sends requests to any other address.
const PUSH_HOSTS = ['fcm.googleapis.com', 'android.googleapis.com', 'push.apple.com', 'push.services.mozilla.com', 'notify.windows.com'];
export function pushEndpointOk(endpoint) {
  if (typeof endpoint !== 'string' || endpoint.length > 1200) return false;
  let u; try { u = new URL(endpoint); } catch { return false; }
  if (u.protocol !== 'https:' || u.port || u.username || u.password) return false;
  return PUSH_HOSTS.some(h => u.hostname === h || u.hostname.endsWith('.' + h));
}

export async function generateVapidKeys() {
  const kp = await subtle().generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
  const publicKey = b64urlEncode(new Uint8Array(await subtle().exportKey('raw', kp.publicKey)));   // 65 bytes, uncompressed
  const privateJwk = await subtle().exportKey('jwk', kp.privateKey);
  return { publicKey, privateJwk };
}

export async function vapidJwt({ endpoint, privateJwk, subject, nowSec = Math.floor(Date.now() / 1000) }) {
  const enc = (o) => b64urlEncode(te.encode(JSON.stringify(o)));
  const unsigned = enc({ typ: 'JWT', alg: 'ES256' }) + '.' + enc({ aud: new URL(endpoint).origin, exp: nowSec + 12 * 3600, sub: subject });
  const key = await subtle().importKey('jwk', { ...privateJwk, key_ops: ['sign'] }, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
  const sig = new Uint8Array(await subtle().sign({ name: 'ECDSA', hash: 'SHA-256' }, key, te.encode(unsigned)));   // raw r||s, as JWT ES256 wants
  return unsigned + '.' + b64urlEncode(sig);
}

// Sends one content-free push. Returns { ok, status, gone } (gone = the phone unsubscribed).
export async function sendPush({ fetch, endpoint, publicKey, privateJwk, subject, nowSec }) {
  if (!pushEndpointOk(endpoint)) return { ok: false, status: 0, gone: true, detail: 'not a push service address' };
  const jwt = await vapidJwt({ endpoint, privateJwk, subject, nowSec });
  let r;
  try {
    r = await fetch(endpoint, { method: 'POST', headers: { TTL: '86400', Urgency: 'normal', Authorization: `vapid t=${jwt}, k=${publicKey}`, 'Content-Length': '0' } });
  } catch (e) { return { ok: false, status: 0, gone: false, detail: 'network' }; }
  return { ok: r.status >= 200 && r.status < 300, status: r.status, gone: r.status === 404 || r.status === 410, detail: 'HTTP ' + r.status };
}

export { b64urlDecode };
